window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[306]={"id":"306","numero":306,"titre":"Tumeurs de l'ovaire","objectifs":[{"id":"306-1","rang":"A","rubrique":"Définition","titre":"Connaître les principaux types de tumeurs primitives bénignes et malignes de l’ovaire","contenu":"<div class=\"notion-course\"><p>L'ovaire est une <span>glande mixte</span> faite de plusieurs tissus aux fonctions complémentaires : la <span>zone corticale</span> contient les follicules (<span class=\"nc-pink nc-bold\">ovocytes</span>) et le stroma (<span class=\"nc-pink nc-bold\">cordons sexuels</span> + <span class=\"nc-blue_bg\">cellules</span> hormonosécrétantes), la <span>zone médullaire</span> centrale est faite de tissu conjonctif lâche (nerfs, vaisseaux, lymphatiques), et la surface est recouverte par un épithélium <span>mésothélial</span> qui explique que les tumeurs épithéliales représentent <span>~ 90 %</span> des tumeurs organiques.</p>\n\n      <table>\n        <thead>\n          <tr><th>Origine</th><th>Tumeurs bénignes</th><th>Tumeurs malignes</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Épithéliale</strong><br>(<span>~ 90 %</span> des tumeurs organiques)</td>\n            <td>Cystadénome / adénofibrome <strong><span class=\"nc-red nc-bold\">séreux</span></strong>, <strong><span class=\"nc-red nc-bold\">mucineux</span></strong>, <strong>endométrioïde</strong> · <span class=\"nc-red_bg\">tumeur de </span><strong><span class=\"nc-red_bg\">Brenner</span> bénigne</strong></td>\n            <td>Adénocarcinome <strong><span class=\"nc-red nc-bold\">séreux</span> haut <span>grade</span></strong> (le + fréquent) · <span class=\"nc-red nc-bold\">séreux</span> bas grade · <span class=\"nc-red nc-bold\">mucineux</span> · endométrioïde · <span class=\"nc-red nc-bold\">à </span><span><span class=\"nc-red nc-bold\">cellules claires</span></span> · Brenner maligne · <strong>carcinosarcome</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Germinale</strong><br>(femme <span>jeune</span>)</td>\n            <td><strong>Tératome mature</strong> = kyste dermoïde</td>\n            <td><span class=\"nc-red_bg\">Tératome </span><span><span class=\"nc-red_bg\">immature</span></span> · <strong><span class=\"nc-red_bg\">dysgerminome</span></strong> · tumeur du sac vitellin (<em>yolk sac</em>) · <span><span class=\"nc-red_bg\">carcinome</span></span><span class=\"nc-red_bg\"> embryonnaire</span> · choriocarcinome</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-pink nc-bold\">Cordons sexuels</span> / stroma</strong></td>\n            <td><strong>Fibrome</strong> · thécome · fibrothécome</td>\n            <td>Tumeur de la <strong>granulosa</strong> (adulte / juvénile) · à cellules de <strong>Sertoli</strong> · à cellules de <strong>Leydig</strong> · <strong>Sertoli-Leydig</strong> (svt sécrétion hormonale)</td>\n          </tr>\n          <tr>\n            <td><strong>Métastatique</strong><br>(<span>~ 10 %</span> des malignes)</td>\n            <td>—</td>\n            <td><strong><span class=\"nc-yellow_bg\">Tumeur de Krukenberg</span></strong> (<span class=\"nc-red nc-bold\">adénocarcinome </span><span><span class=\"nc-red nc-bold\">gastrique</span></span><span class=\"nc-red nc-bold\"> à cellules indépendantes en bague à chaton</span>) · cancers <span>colorectaux</span> · <span><span class=\"nc-red nc-bold\">sein</span></span> · <span>mélanomes</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong>Drapeau métastases.</strong> Les tumeurs métastatiques sont évoquées en cas de tumeurs <span><span class=\"nc-red nc-bold\">bilatérales</span></span>. La <span class=\"nc-yellow_bg\">tumeur de </span><strong><span class=\"nc-yellow_bg\">Krukenberg</span></strong> correspond à un adénocarcinome <span><span class=\"nc-red nc-bold\">gastrique</span></span> (plus rare : <span>colorectal</span>) à <span><span class=\"nc-blue_bg\">cellules</span> indépendantes en bague à chaton</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 44 — <span>Tuméfaction</span> pelvienne · 301 — Tumeur colon - rectum · 303 — Tumeur estomac · 312 — Tumeur sein · 41 — Endométriose</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Ovaires202018-RPC-Cancer20pithlial.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cancer épithélial de l’ovaire, 2018</a></li></ul></details>","frequence":1},{"id":"306-2","rang":"B","rubrique":"Définition","titre":"Connaître les principaux types histologiques des tumeurs bénignes et malignes","contenu":"<div class=\"notion-course\"><p>La <span>classification OMS 2020</span> affine la stratification de l'obj-0 en sous-types histologiques précis. L'enjeu n'est pas mnémotechnique : chaque sous-type a un <span>pronostic</span> et une <span>thérapeutique ciblée</span> propres (notamment les mutations <span><span class=\"nc-blue_bg\">BRCA1</span>/2</span>, l'<span>instabilité microsatellite</span> et les inhibiteurs de <span>PARP</span>).</p>\n\n      <table>\n        <thead>\n          <tr><th>Type</th><th>Bénin / Borderline</th><th>Malin</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Séreux</span></strong></td>\n            <td><strong>Bénin :</strong> cystadénome · adénofibrome · cystadénofibrome<br><strong>Borderline :</strong> séreuse borderline · micropapillaire</td>\n            <td>Adénocarcinome <span class=\"nc-red nc-bold\">séreux</span> <span>haut grade</span> <em>(le + fréquent)</em> · adénocarcinome <span class=\"nc-red nc-bold\">séreux</span> bas <span>grade</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mucineux</strong></td>\n            <td><strong>Bénin :</strong> cystadénome mucineux<br><strong>Borderline :</strong> mucineuse borderline</td>\n            <td>Adénocarcinome mucineux (expansif ou infiltratif)</td>\n          </tr>\n          <tr>\n            <td><strong>Endométrioïde</strong></td>\n            <td><strong>Bénin :</strong> cystadénome / adénofibrome endométrioïde<br><strong>Borderline :</strong> endométrioïde borderline</td>\n            <td>Adénocarcinome endométrioïde</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">À cellules claires</span></strong></td>\n            <td><strong>Bénin :</strong> cystadénome<br><strong>Borderline :</strong> borderline <span class=\"nc-red nc-bold\">à cellules claires</span></td>\n            <td>Adénocarcinome <span class=\"nc-red nc-bold\">à </span><span><span class=\"nc-red nc-bold\">cellules claires</span></span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Tumeurs <span class=\"nc-red nc-bold\">borderline</span> (TBO).</strong> Représentent <span>10-20 %</span> des tumeurs épithéliales non bénignes. Âge médian inférieur de <span><span class=\"nc-green_bg nc-bold\">-10 ans</span></span> aux tumeurs <span class=\"nc-red nc-bold\">malignes</span> (1/3 chez <span>&lt; 40 ans</span>). Excellent pronostic mais risque de <span class=\"nc-red nc-bold\">récidive</span> tardive (<span>&gt; 20 ans</span>). <span>IRM pelvienne</span> essentielle, mais seule l'analyse <span>histologique</span> permet le diagnostic.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 293 — Anapath</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Ovaires202018-RPC-Cancer20pithlial.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cancer épithélial de l’ovaire, 2018</a></li></ul></details>","frequence":1},{"id":"306-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie et le pronostic des tumeurs bénignes et malignes","contenu":"<div class=\"notion-course\"><table>\n        <thead>\n          <tr><th>Type</th><th>Fréquence</th><th>Âge médian</th><th>Survie / <span>Pronostic</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Bénignes</strong></td>\n            <td>Majorité des tumeurs ovariennes</td>\n            <td><span>~ <span class=\"nc-pink nc-bold\">30 ans</span></span></td>\n            <td><strong>Bon <span>pronostic</span>.</strong> Guéries après <span>exérèse</span> chirurgicale pour fibrothécome, cystadénome <span class=\"nc-red nc-bold\">séreux</span> ou <span class=\"nc-red nc-bold\">mucineux</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Malignes</strong></td>\n            <td><span>5 200 nouveaux cas / an</span> (France, 2018)<br><span>5ᵉ cancer féminin</span> · <span>2ᵉ gynéco</span> après endomètre</td>\n            <td><span><span class=\"nc-pink nc-bold\">65-68 ans</span></span></td>\n            <td><span>4ᵉ cause de décès par cancer féminin</span> (1ʳᵉ par cancer gynéco)<br><span class=\"nc-yellow_bg\">Survie globale à</span><span><span class=\"nc-yellow_bg\"> 5 ans</span></span> : <span>45 %</span><br><span class=\"nc-green nc-bold\">FIGO I</span> : <span>90 %</span> · FIGO ≥ III : <span>&lt; 40 %</span><br>Diagnostic <span>tardif dans 75 %</span> des cas</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Facteurs pronostiques.</strong> Le facteur pronostique le plus important est la <strong><span class=\"nc-yellow_bg\">résécabilité de la maladie</span></strong> et le <strong><span class=\"nc-yellow_bg\">résidu tumoral post-opératoire</span></strong>. S'y associent l'<span>âge</span>, l'<span>état général</span>, le <span><span class=\"nc-red_bg\">type histologique</span></span>, le grade et la réponse à la chimiothérapie. Le pronostic est <span>amélioré</span> par la PEC dans des centres experts (taux de résection R0 supérieur, accès aux essais cliniques).</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Pronostic global <span class=\"nc-red nc-bold\">médiocre</span>.</strong> Le diagnostic au <span>stade tardif (75 % des cas)</span> explique la mortalité élevée du cancer de l'ovaire. La tumeur <strong>germinale</strong> est le <span class=\"nc-red_bg\">type histologique</span> de meilleur pronostic, car souvent découverte plus précocement chez la femme jeune.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers · 300 — Tumeur col-corps utérin · 312 — Tumeur sein · 124 — Ménopause - andropause</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Ovaires202018-RPC-Cancer20pithlial.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cancer épithélial de l’ovaire, 2018</a></li></ul></details>","frequence":1},{"id":"306-4","rang":"B","rubrique":"Eléments physiopathologiques","titre":"Connaître la physiopathologie des cancers de l’ovaire","contenu":"<div class=\"notion-course\"><p>Il existe <span>deux théories complémentaires</span> sur l'origine du cancer de l'ovaire. Toutes deux convergent vers une <span>origine multifocale</span>, ce qui explique la <span>latence <span class=\"nc-blue nc-bold\">clinique</span></span> et la <span><span class=\"nc-red nc-bold\">dissémination péritonéale</span> <span class=\"nc-green nc-bold\">précoce</span></span>.</p>\n\n      <table>\n        <thead>\n          <tr><th>Théorie</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Origine tubaire</strong></td>\n            <td>La <span>trompe de Fallope</span> serait le point de départ. Le <span><span class=\"nc-orange nc-bold\">carcinome séreux intra-épithélial tubaire</span> (STIC)</span> est la 1ʳᵉ <span>lésion</span> histologique des <span>carcinomes <span class=\"nc-red nc-bold\">séreux</span> haut grade</span> (= forme la plus fréquente). L'ovaire est secondairement envahi par des <span class=\"nc-blue_bg\">cellules</span> dysplasiques d'origine tubaire.</td>\n          </tr>\n          <tr>\n            <td><strong>Cicatrisation ovarienne</strong><br>(<em>ovulation incessante</em>)</td>\n            <td>À chaque <span>ovulation</span>, <span>rupture</span> de l'épithélium de surface → prolifération cicatricielle → <span><span class=\"nc-red nc-bold\">kystes</span> d'inclusion</span> → accumulation d'<span>anomalies génétiques</span> au fil des cycles. Justifie le rôle <span>protecteur</span> des situations qui diminuent les ovulations (<span>parité</span>, <span>allaitement</span>, <span>CO œstroprogestative</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table>\n        <thead>\n          <tr><th>Mode de dissémination</th><th>Cibles</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Loco-régional</strong><br>(péritoine ++)</td>\n            <td>Franchissement de la corticale ovarienne → dissémination très rapide vers les <span><span class=\"nc-red nc-bold\">organes pelviens</span></span>, puis vers <span>l'<span class=\"nc-red nc-bold\">ensemble de la cavité péritonéale</span></span> au gré du flux du liquide péritonéal (= <strong>carcinose péritonéale</strong>).</td>\n          </tr>\n          <tr>\n            <td><strong>À distance</strong></td>\n            <td>Dissémination <span>lymphatique</span> (ganglions <span class=\"nc-purple nc-bold\">pelviens</span> + <span class=\"nc-purple nc-bold\">lomboaortiques</span>), puis <span>hématogène</span> (poumons, <span class=\"nc-red nc-bold\">foie</span>, cerveau).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pourquoi un diagnostic si tardif ?</strong> L'extension péritonéale <span class=\"nc-green nc-bold\">précoce</span> et silencieuse explique que <span>3/4 des cancers sont diagnostiqués à un stade avancé</span> de carcinose. L'absence de <span>dépistage</span> efficace aggrave ce retard.\n      </div></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Ovaires202018-RPC-Cancer20pithlial.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cancer épithélial de l’ovaire, 2018</a></li></ul></details>","frequence":2},{"id":"306-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux facteurs de risque/protecteurs associés au cancer de l’ovaire","contenu":"<div class=\"notion-course\"><div class=\"callout callout-danger\">\n        <strong>Pas de <span>dépistage</span>.</strong> Il n'existe <span>aucun dépistage efficace</span> du cancer de l'ovaire — d'où l'importance d'une <strong>consultation oncogénétique systématique</strong> dès qu'un cancer ovarien est diagnostiqué.\n      </div>\n\n      <table>\n        <thead>\n          <tr><th>FdR génétiques (<span>10-20 %</span>)</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>ATCD familial 1ᵉʳ degré</strong></td>\n            <td>Augmente le risque de <span>5 %</span> de développer un cancer de l'ovaire au cours de la vie.</td>\n          </tr>\n          <tr>\n            <td><strong>Mutations <span class=\"nc-blue_bg\">BRCA1</span> / <span class=\"nc-blue_bg\">BRCA2</span></strong></td>\n            <td><span>80 % des formes héréditaires</span> · cancers <span>avant 60 ans</span> · <span>consultation oncogénétique systématique</span> chez <span class=\"nc-yellow_bg nc-bold\">toute</span> patiente atteinte · meilleur <span>pronostic</span> (sensibilité aux <span>inhibiteurs de PARP</span>).</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-red nc-bold\">Syndrome de Lynch</span></span></strong><br>(défaut <span>MMR</span> — <span>MSI-H</span>)</td>\n            <td>Concerne surtout colorectal + endomètre, mais aussi ovaire. À évoquer si cancer <span>&lt; 70 ans</span> ou histoire familiale évocatrice.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table>\n        <thead>\n          <tr><th>Autres FdR</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Extrinsèques</strong></td>\n            <td><span><span class=\"nc-orange_bg\">Tabagisme</span></span> · <strong><span class=\"nc-red nc-bold\">exposition professionnelle à l'amiante</span></strong> (CIRC, 2012) · <span>surpoids</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Gynécologiques</strong></td>\n            <td>Augmentation du nombre de cycles : <span><span class=\"nc-blue_bg\">âge</span></span> · <span><span class=\"nc-blue_bg\">nulliparité</span></span> · <span><span class=\"nc-blue_bg\">puberté / règles précoces</span></span> · <span><span class=\"nc-blue_bg\">ménopause tardive</span></span>.<br><span>Iatrogène</span> : <span>THM œstrogénique</span> · <span>clomifène / FIV</span>.<br><span><span class=\"nc-red nc-bold\">Infertilité</span></span> = FdR avéré.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table>\n        <thead>\n          <tr><th>Facteurs protecteurs</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Diminution du nb d'ovulations</strong></td>\n            <td><span class=\"nc-green_bg\">Grossesse</span> · <span class=\"nc-green_bg\">multiparité</span> · <span class=\"nc-green_bg\">allaitement</span> · <span><span class=\"nc-pink nc-bold\">contraception orale</span> œstroprogestative</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Suppression du tissu cible</strong></td>\n            <td><span class=\"nc-pink_bg\">Ligature des trompes</span> · <span><span class=\"nc-pink_bg\">salpingectomie bilatérale</span></span> (++ si <span>BRCA</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers · 35 — Anomalies cycle menstruel - métrorragie · 124 — Ménopause - andropause</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Ovaires202018-RPC-Cancer20pithlial.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cancer épithélial de l’ovaire, 2018</a></li></ul></details>","frequence":1},{"id":"306-6","rang":"B","rubrique":"Diagnostic","titre":"Connaître les indications de la cœlioscopie","contenu":"<div class=\"notion-course\"><ul><li>Une masse annexielle n’impose pas toujours une cœlioscopie : les kystes simples à faible risque peuvent relever d’une surveillance adaptée.</li><li>Chirurgie si torsion/complication, <span class=\"nc-red nc-bold\">symptômes</span> persistants, taille ou aspect préoccupant, ou indication oncologique. Voie d’abord et geste selon risque de <span class=\"nc-red_bg\">malignité</span> et objectif de conservation.</li><li>Masse présumée bénigne : <span class=\"nc-pink nc-bold\">kystectomie</span> ou <span class=\"nc-pink nc-bold\">annexectomie</span> selon âge, réserve ovarienne et contexte, avec précautions pour éviter la <span class=\"nc-red nc-bold\">rupture</span> et analyse anatomopathologique.</li><li>Masse suspecte de malignité : adresser à une équipe de gynécologie oncologique pour stratégie de diagnostic/stadification ; éviter la ponction non planifiée d’une masse ovarienne isolée.</li><li>En maladie avancée, une biopsie de carcinose ou d’un site accessible peut être indiquée avant traitement néoadjuvant selon décision multidisciplinaire ; ne pas confondre ce geste avec la ponction d’un kyste isolé.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Ovaires202018-RPC-Cancer20pithlial.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cancer épithélial de l’ovaire, 2018</a></li></ul></details>","frequence":4},{"id":"306-7","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications de l’imagerie d’une tumeur de l’ovaire","contenu":"<div class=\"notion-course\"><p>L'imagerie pelvienne suit une <span>hiérarchie stricte</span> selon le contexte. L'<span><span class=\"nc-blue nc-bold\">échographie</span> pelvienne</span> est l'examen de 1ʳᵉ intention devant toute suspicion de <span><span class=\"nc-red_bg\">masse</span></span><span class=\"nc-red_bg\"> pelvienne</span>, complétée par l'<span><span class=\"nc-blue_bg\">IRM</span></span> en cas d'incertitude, puis par la <span><span class=\"nc-yellow_bg\">TDM-TAP</span></span> pour le <span>bilan d'extension</span> après <span>diagnostic positif</span>.</p>\n\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Indications</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Échographie</span> pelvienne</strong><br>(1ʳᵉ intention)</td>\n            <td>Voie <span>sus-pubienne vessie pleine</span> + voie <span>endovaginale vessie vide</span> + <span><span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> abdominale</span></span> ± <span><span class=\"nc-blue_bg\">écho-doppler couleur</span></span>.<br>Classe la tumeur en <strong><span class=\"nc-green_bg\">kyste fonctionnel</span></strong> <span>vs</span> <strong><span class=\"nc-yellow_bg\">kyste organique</span></strong> <span>vs</span> <strong><span><span class=\"nc-red_bg\">critères de</span></span><span class=\"nc-red_bg\"> malignité</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">IRM</span></span><span class=\"nc-blue_bg\"> abdomino-pelvienne</span></strong></td>\n            <td><strong>Indications :</strong> <span><span class=\"nc-yellow_bg\">masse</span></span><span class=\"nc-yellow_bg\"> ovarienne indéterminée</span> (caractérisation par <span>diffusion</span> + perfusion) · <span><span class=\"nc-blue nc-bold\">bilan d'extension</span></span><span class=\"nc-blue nc-bold\"> locorégional</span> des formes localisées · suspicion de TBO (intérêt majeur).<br><strong>Non-indication :</strong> pas d'intérêt si <span><span class=\"nc-blue nc-bold\">échographie</span></span> suspecte d'emblée une maladie avancée avec carcinose (on passe direct au <span><span class=\"nc-yellow_bg\">TDM</span></span><span class=\"nc-yellow_bg\">-TAP</span>).<br><strong><span>Classification</span> <span>O-RADS</span></strong> (<em>Ovarian-Adnexal Reporting &amp; Data System</em>) :<br><strong>O-RADS 1-2</strong> = presque toujours bénin → <span>surveillance possible</span><br><strong>O-RADS 3</strong> = risque faible → <span>avis spécialisé</span><br><strong>O-RADS 4-5</strong> = <span>tumeur borderline ou invasive suspectée</span> → <span><span class=\"nc-blue_bg\">IRM</span></span> injectée + <span>prise en charge chirurgicale</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>TDM</span> thoraco-abdomino-pelvien</strong><br>(<span><span class=\"nc-yellow_bg\">TDM</span></span><span class=\"nc-yellow_bg\">-TAP</span>)</td>\n            <td><strong>Systématique</strong> pour le <span>bilan d'extension</span> après <span>diagnostic positif</span>. Apprécie l'importance et la distribution de la <span>carcinose péritonéale</span> (++ étage supérieur de l'abdomen), explore les chaînes ganglionnaires rétropéritonéales / pelviennes / <span class=\"nc-purple nc-bold\">lomboaortiques</span>. Coupes thoraciques : recherche d'<span>épanchement pleural</span> (fréquent <span>stade</span> IV) et de ganglions médiastinaux ou <span class=\"nc-yellow_bg nc-bold\">sus-claviculaires</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Optionnels</strong></td>\n            <td><strong><span><span>TEP</span>-<span>TDM</span></span> 18FDG :</strong> complément du <span>TDM</span> pour les <span><span class=\"nc-red nc-bold\">stades avancés</span></span> ou les <span><span class=\"nc-red nc-bold\">récidives</span></span> (suspicion de rechute avec <span>TDM</span> normal).<br><strong>Imagerie mammaire</strong> (<span>mammographie</span> + écho) : éliminer un cancer du <span class=\"nc-red nc-bold\">sein</span> concomitant en cas de <span class=\"nc-red nc-bold\">carcinose péritonéale</span> avec masses annexielles.<br><strong><span>Endoscopie</span> digestive</strong> (<span>FOGD</span> + <span>coloscopie</span>) : éliminer une origine digestive primitive si <span><span class=\"nc-pink nc-bold\">CA 19-9</span></span> augmenté ou image <span>TDM</span>-TAP suspecte.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table>\n        <thead>\n          <tr><th>Critères échographiques de <span class=\"nc-red_bg\">malignité</span></th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Taille de la <span>masse</span></strong></td>\n            <td><span>&gt; 7 cm</span> (cut-off rang A).</td>\n          </tr>\n          <tr>\n            <td><strong>Présence de cloisons</strong></td>\n            <td>Caractère <span>multiloculaire</span> · cloisons épaisses (<span>&gt; 3 mm</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Parois épaissies</strong></td>\n            <td>Irrégularités des parois interne ou externe — <em>signe majeur</em> de malignité.</td>\n          </tr>\n          <tr>\n            <td><strong>Composantes solides</strong></td>\n            <td><span><span class=\"nc-red_bg\">Végétations endo/exo-kystiques</span></span> plus ou moins épaisses et confluentes.</td>\n          </tr>\n          <tr>\n            <td><strong>Vascularisation <span>doppler</span></strong></td>\n            <td><span><span class=\"nc-yellow_bg\">Hypervascularisation</span></span> (néovascularisation) + <span><span class=\"nc-yellow_bg\">diminution de la résistivité</span></span> (vitesse de circulation sanguine).</td>\n          </tr>\n          <tr>\n            <td><strong>Signes associés</strong></td>\n            <td><span><span class=\"nc-red_bg\">Ascite</span></span> · <span><span class=\"nc-red_bg\">adénopathies</span></span> · <span><span class=\"nc-red_bg\">bilatéralité</span></span> · nodules de carcinose (peu visibles en écho, mieux vus en <span>TDM</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>CAT échographique synthétique.</strong> <span>Critères de</span> bénignité tous présents (<span>&lt; 7 cm</span>, uniloculaire, anéchogène pur, parois fines, pas de végétation, pas de vascularisation pathologique, pas d'<span class=\"nc-red_bg\">ascite</span>) → <span><span class=\"nc-green_bg\">surveillance</span> écho à M1-M3</span>. <span class=\"nc-red_bg\">Persistance</span> à<span> 3 mois</span> → <span class=\"nc-yellow_bg\">kyste organique</span>. Critère(s) suspects → <span><span class=\"nc-blue_bg\">IRM</span></span><span class=\"nc-blue_bg\"> + </span><span><span class=\"nc-blue_bg\">marqueurs</span></span>. Carcinose / <span class=\"nc-red_bg\">ascite</span> → <span><span class=\"nc-yellow_bg\">TDM-TAP</span> injecté</span>.\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>Piège kyste dermoïde.</strong> Diagnostic souvent fait à l'écho seule grâce à l'aspect <span class=\"nc-blue_bg\">hétérogène</span> + zones hyperéchogènes (<span class=\"nc-blue nc-bold\">cheveux</span>, dents) + <strong>protubérance de Rokitanski</strong>. Le <span>TDM</span> aide en montrant le <span>contenu graisseux caractéristique</span> + calcifications. Mais <span>risque élevé de <span class=\"nc-orange nc-bold\">torsion</span> d'annexe</span> (kyste <span class=\"nc-red nc-bold\">lourd</span>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 44 — Tuméfaction pelvienne · 40 — Algies pelviennes</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Ovaires202018-RPC-Cancer20pithlial.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cancer épithélial de l’ovaire, 2018</a></li></ul></details>","frequence":5,"liens":[{"href":"https://radiopaedia.org/articles/ovarian-tumours","label":"Radiopaedia : Ovarian tumours"},{"href":"https://radiopaedia.org/articles/ovary","label":"Radiopaedia : Ovary"},{"href":"https://radiopaedia.org/articles/ovarian-cyst-2","label":"Radiopaedia : Ovarian cyst 2"},{"href":"https://radiopaedia.org/articles/ovarian-torsion","label":"Radiopaedia : Ovarian torsion"},{"href":"https://radiopaedia.org/articles/hemorrhagic-ovarian-cyst-2","label":"Radiopaedia : Hemorrhagic ovarian cyst 2"}]},{"id":"306-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’intérêt diagnostique et pronostique de l’anapath","contenu":"<div class=\"notion-course\"><div class=\"callout callout-danger\">\n        <strong><span class=\"nc-red nc-bold\">Spécificité</span> cancer de l'ovaire.</strong> C'est l'un des <span>rares cancers</span> dont le diagnostic n'est <span>pas obtenu en pré-opératoire</span> — le <span class=\"nc-red nc-bold\">diagnostic est </span><span><span class=\"nc-red nc-bold\">chirurgical</span></span><span class=\"nc-red nc-bold\"> dans la majorité des cas</span>. Recommandé <span>avant <span class=\"nc-yellow_bg nc-bold\">toute</span> chimiothérapie</span>.\n      </div>\n\n      <table>\n        <thead>\n          <tr><th><span>Stade</span> FIGO</th><th>Modalité de prélèvement</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Stades précoces</strong><br>(FIGO 1-2)</td>\n            <td>Exploration chirurgicale → <strong><span class=\"nc-green_bg\">annexectomie diagnostique</span></strong> + anapath.<br><strong>&lt; 10 cm :</strong> <span>cœlioscopie</span> privilégiée.<br><strong><span>&gt; 10 cm</span> ou <span class=\"nc-orange_bg\">diagnostic incertain</span> :</strong> <span><span class=\"nc-orange_bg nc-bold\">laparotomie</span></span> (éviter <span><span class=\"nc-red nc-bold\">rupture</span></span>).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Stades avancés</span></strong><br>(FIGO 3-4)</td>\n            <td><strong>Cœlioscopie diagnostique</strong> pour <span>biopsies</span> multiples des nodules de carcinose.</td>\n          </tr>\n          <tr>\n            <td><strong>Patiente non opérable</strong></td>\n            <td><strong><span>Biopsie</span> sous <span class=\"nc-blue_bg\">radiologie interventionnelle</span></strong> (percutanée sous <span>TDM</span> ou <span>échographie</span> d'un <span>nodule</span> de carcinose).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table>\n        <thead>\n          <tr><th>Type de prélèvement</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Diagnostic positif</span></strong></td>\n            <td><span class=\"nc-yellow_bg nc-bold\">Matériel </span><strong><span class=\"nc-yellow_bg nc-bold\">biopsique</span></strong> (et <span>non cytologique</span>) · <span>biopsies</span> <span>multiples</span> et de <span>bonne taille</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Mutations somatiques</strong><br>(sur la tumeur)</td>\n            <td><strong><span class=\"nc-blue_bg\">BRCA1</span> / <span class=\"nc-blue_bg\">BRCA2</span> systématique</strong> : si mutation → conseil oncogénétique + <span>inhibiteurs de PARP</span> adjuvant.<br><strong><span>Score</span> HRD</strong> (<em>Homologous Recombination Deficiency</em>) : recherché si <span>BRCA sauvage</span> — conditionne l'éligibilité aux <span>PARPi (olaparib, niraparib)</span> en 1ʳᵉ ligne.<br><strong>Instabilité microsatellites (Lynch) :</strong> non systématique, à réaliser si cancer <span>&lt; 70 ans</span> ou histoire personnelle / familiale évocatrice.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 293 — Anapath · 292 — Diagnostic des cancers</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Ovaires202018-RPC-Cancer20pithlial.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cancer épithélial de l’ovaire, 2018</a></li></ul></details>","frequence":1},{"id":"306-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux marqueurs sériques et leur bon usage dans les tumeurs de l’ovaire","contenu":"<div class=\"notion-course\"><p>Le choix des marqueurs sériques dépend du contexte <span class=\"nc-blue nc-bold\">clinique</span> (femme jeune / âgée) et de la suspicion histologique (épithéliale / germinale / cordon sexuel). Le <span><span class=\"nc-pink nc-bold\">CA 125</span></span> est le marqueur de référence du cancer épithélial — mais ni assez sensible ni assez spécifique pour porter le diagnostic à lui seul.</p>\n\n      <table>\n        <thead>\n          <tr><th>Contexte</th><th>Marqueurs à doser</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Suspicion de cancer épithélial</strong><br>(1ʳᵉ intention)</td>\n            <td><strong><span><span class=\"nc-yellow_bg\">CA 125</span></span></strong> (assez spécifique) · <strong><span><span class=\"nc-yellow_bg\">CA 19-9</span></span></strong> (souvent élevé dans les formes mucineuses) · <strong><span><span class=\"nc-yellow_bg\">ACE</span></span></strong> (moins spécifique).</td>\n          </tr>\n          <tr>\n            <td><strong>Suspicion tumeur germinale</strong><br>(femme <span>jeune</span>)</td>\n            <td><strong><span><span class=\"nc-blue_bg\">LDH</span></span> + α-fœtoprotéine</strong> (élevés dans les dysembryomes) · <strong><span class=\"nc-blue_bg\">hCG</span></strong> (élevés dans les choriocarcinomes).</td>\n          </tr>\n          <tr>\n            <td><strong>Suspicion tumeur des <span class=\"nc-pink nc-bold\">cordons sexuels</span></strong><br>(signes d'hyperœstrogénie ou tumeur de la granulosa)</td>\n            <td><strong><span class=\"nc-pink_bg\">Estradiol</span> + AMH + <span class=\"nc-pink_bg\">inhibine B</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-yellow_bg\">Masse</span></span><span class=\"nc-yellow_bg\"> ovarienne indéterminée</span> à l'imagerie</strong></td>\n            <td><strong><span class=\"nc-yellow_bg\">HE4</span></strong> (<em>Human Epididymal Protein 4</em>) — peu utilisé, <span>non remboursé</span>. S'interprète selon le <span><span class=\"nc-blue nc-bold\">score ROMA</span></span> (statut ménopausique + <span>CA 125</span> + <span><span class=\"nc-yellow_bg\">HE4</span></span>) — cut-off : <span>11,4 % préménopause</span> · <span>29,9 % postménopause</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong><span><span class=\"nc-pink nc-bold\">CA 125</span></span> : pièges à connaître.</strong> <strong><span class=\"nc-red nc-bold\">Sensibilité imparfaite</span></strong> : <span>faux négatifs possibles</span> (un <span><span class=\"nc-pink nc-bold\">CA 125</span> normal n'élimine pas un cancer</span>). <strong><span class=\"nc-red nc-bold\">Spécificité</span> <span class=\"nc-red nc-bold\">imparfaite</span></strong> : c'est aussi un <span>marqueur d'irritation péritonéale</span> (<span>endométriose</span>, <span>infection</span>, autres carcinomes non ovariens). Donc <span>il n'est pas recommandé</span> de se fonder uniquement sur le <span><span class=\"nc-pink nc-bold\">CA 125</span></span> sérique pour évaluer la résécabilité d'une carcinose.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong><span>Suivi</span> post-traitement.</strong> Si <span><span class=\"nc-pink nc-bold\">CA 125</span> &lt; 10 UI/mL</span> après traitement, <span class=\"nc-yellow_bg nc-bold\">toute</span> élévation <span>&gt; 20 UI/mL</span> contrôlée à<span> 15 jours</span> est suspecte de <span class=\"nc-red nc-bold\">récidive</span> — peut précéder les signes cliniques. La décroissance des marqueurs juge en partie l'efficacité du traitement.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 290 — Epidémiologie cancers</em></p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Ovaires202018-RPC-Cancer20pithlial.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cancer épithélial de l’ovaire, 2018</a></li></ul></details>","frequence":2}],"astuces":[],"strategie":{"redflags":"<p><strong>✅ <span class=\"kw-def\">Critères de</span> bénignité (tous requis)</strong></p><p>→ Si TOUS réunis : contrôle écho à <span class=\"kw-chiffre\">3 mois</span> (exclure un kyste fonctionnel). Persistance = origine organique.</p><ul><li>Image <span class=\"kw-clinique\">uniloculaire</span> ou pluriloculaire à cloison <span class=\"kw-chiffre\">très fine (&lt; 3 mm)</span></li><li><span class=\"kw-clinique\">Absence de zone solide</span> (pas de végétation), <span class=\"kw-clinique\">paroi fine</span></li><li>Vascularisation <span class=\"kw-clinique\">périphérique régulière</span>, index de résistance <span class=\"kw-chiffre\">&gt; 0,50</span></li><li>Kyste <span class=\"kw-chiffre\">&lt; 7 cm</span>, <span class=\"kw-clinique\">absence d’ascite</span></li></ul><p><strong>🔴 <span class=\"kw-def\">Critères de</span> malignité</strong></p><p>→ Absence de <span class=\"kw-def\">critères de</span> bénignité : <span class=\"kw-imagerie\">IRM</span> ou <span class=\"kw-ttt\">cœlioscopie</span> s’impose.</p><ul><li><span class=\"kw-clinique\">Masse</span> <span class=\"kw-alerte\">solide ou mixte</span>, taille <span class=\"kw-chiffre\">≥ 7 cm</span></li><li><span class=\"kw-alerte\">Végétations</span> endo/exo-kystiques, cloisons épaisses, parois épaissies, contours irréguliers</li><li>Doppler : <span class=\"kw-alerte\">hypervascularisation</span> (néovascularisation) + <span class=\"kw-alerte\">baisse de la résistivité</span></li><li><span class=\"kw-alerte\">Bilatéralité</span>, <span class=\"kw-alerte\">ascite</span>, carcinose péritonéale, <span class=\"kw-clinique\">adénopathies</span></li></ul>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/ovarian-tumours","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/ovary","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/ovarian-cyst-2","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/ovarian-torsion","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/hemorrhagic-ovarian-cyst-2","label":"radiopaedia.org"},{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"},{"href":"https://cngof.fr/app/uploads/2025/11/Ovaires202018-RPC-Cancer20pithlial.pdf","label":"CNGOF · Cancer épithélial de l’ovaire, 2018"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Masse annexielle : urgence ou bilan programmé ?","detail":"<ul><li>Douleur, taille, âge, ascite et contexte familial.</li></ul>","branches":[{"label":"Torsion/rupture suspectée","to":"urgent"},{"label":"Stable","to":"imagerie"}]},{"id":"urgent","kind":"urgent","label":"Évaluation chirurgicale urgente","detail":"<ul><li>Ne pas retarder si forte suspicion de torsion.</li></ul>","branches":[]},{"id":"imagerie","kind":"decision","label":"Échographie puis IRM si indéterminée","detail":"<ul><li>Scanner si bilan d’extension indiqué ; pas de dépistage général par CA125.</li></ul>","branches":[{"label":"Bénigne présumée","to":"benigne"},{"label":"Suspecte","to":"expert"}]},{"id":"benigne","kind":"finish","label":"Surveiller ou opérer selon indication","detail":"<ul><li>Taille, symptômes, persistance et projet ; prévenir les complications.</li></ul>","branches":[]},{"id":"expert","kind":"decision","label":"Centre expert et bilan adapté","detail":"<ul><li>Marqueurs selon âge/type suspecté ; éviter rupture d’une tumeur suspecte.</li></ul>","branches":[{"label":"Confirmation histologique et stratégie","to":"histologie"}]},{"id":"histologie","kind":"finish","label":"Histologie, stade et RCP","detail":"<ul><li>Épithéliale, germinale ou stromale ; chirurgie/traitement adapté et génétique si indiquée.</li></ul>","branches":[]}]},"cards":[{"i":"2420a4790f1a","n":306,"o":"306-1","u":"Définition","t":"Connaître les principaux types de tumeurs primitives bénignes et malignes de l’ovaire","q":"Quels sont les principaux types de tumeurs ovariennes primitives bénignes et malignes d'origine germinale ?","a":"<div class=\"notion-course\"><p>Les principales tumeurs ovariennes primitives d'origine germinale, plus fréquentes chez la <strong>femme jeune</strong>, sont :</p><ul><li>Tumeurs bénignes : le <strong>tératome mature</strong> (également appelé <strong>kyste dermoïde</strong>).</li><li>Tumeurs <span class=\"nc-red nc-bold\">malignes</span> : le <strong><span class=\"nc-red_bg\">tératome immature</span></strong>, le <strong><span class=\"nc-red_bg\">dysgerminome</span></strong>, la <strong>tumeur du sac vitellin</strong> (yolk sac), le <strong><span class=\"nc-red_bg\">carcinome embryonnaire</span></strong>, et le <strong>choriocarcinome</strong>.</li></ul></div>"},{"i":"3e25bb51eca8","n":306,"o":"306-1","u":"Définition","t":"Connaître les principaux types de tumeurs primitives bénignes et malignes de l’ovaire","q":"Quelle est l'origine tissulaire majoritaire des tumeurs ovariennes primitives et quels sont les principaux types de tumeurs bénignes et malignes qui en dérivent ?","a":"<div class=\"notion-course\"><p>L'origine tissulaire majoritaire des tumeurs ovariennes primitives est <strong>épithéliale</strong>, représentant environ <strong>90 %</strong> des tumeurs organiques. Les principaux types incluent :</p><ul><li>Tumeurs bénignes : <strong>cystadénome / adénofibrome <span class=\"nc-red nc-bold\">séreux</span>, <span class=\"nc-red nc-bold\">mucineux</span>, endométrioïde</strong>, et la <strong><span class=\"nc-red_bg\">tumeur de Brenner</span> bénigne</strong>.</li><li>Tumeurs <span class=\"nc-red nc-bold\">malignes</span> : <strong>adénocarcinome <span class=\"nc-red nc-bold\">séreux</span> haut grade</strong> (le plus fréquent), <span class=\"nc-red nc-bold\">séreux</span> bas grade, <span class=\"nc-red nc-bold\">mucineux</span>, endométrioïde, <span class=\"nc-red nc-bold\">à cellules claires</span>, Brenner maligne, et le <strong>carcinosarcome</strong>.</li></ul></div>"},{"i":"807ee03e9d06","n":306,"o":"306-1","u":"Définition","t":"Connaître les principaux types de tumeurs primitives bénignes et malignes de l’ovaire","q":"Qu'est-ce qu'une tumeur de Krukenberg et quelle est son origine ?","a":"<div class=\"notion-course\"><p>La <strong><span class=\"nc-yellow_bg\">tumeur de Krukenberg</span></strong> est une tumeur ovarienne métastatique, représentant environ <strong>10 %</strong> des tumeurs ovariennes <span class=\"nc-red nc-bold\">malignes</span>. Elle est caractérisée histologiquement par des <strong><span class=\"nc-blue_bg\">cellules</span> indépendantes en bague à chaton</strong>. Son origine la plus fréquente est un <strong>adénocarcinome <span class=\"nc-red nc-bold\">gastrique</span></strong>, mais des origines <strong>colorectales</strong> ou mammaires sont <span class=\"nc-red nc-bold\">également</span> possibles.</p></div>"},{"i":"81396f334aed","n":306,"o":"306-1","u":"Définition","t":"Connaître les principaux types de tumeurs primitives bénignes et malignes de l’ovaire","q":"Quels sont les principaux types de tumeurs ovariennes primitives bénignes et malignes d'origine des cordons sexuels / stroma ?","a":"<div class=\"notion-course\"><p>Les principales tumeurs ovariennes primitives dérivant des <span class=\"nc-pink nc-bold\">cordons sexuels</span> / stroma sont :</p><ul><li>Tumeurs bénignes : le <strong>fibrome</strong>, le <strong>thécome</strong>, et le <strong>fibrothécome</strong>.</li><li>Tumeurs <span class=\"nc-red nc-bold\">malignes</span> : la <strong>tumeur de la granulosa</strong> (adulte / juvénile), les <span class=\"nc-red_bg\">tumeurs à </span><strong><span class=\"nc-red_bg\">cellules de Sertoli</span></strong>, à <strong><span class=\"nc-blue_bg\">cellules</span> de Leydig</strong>, et les <span class=\"nc-red_bg\">tumeurs à </span><strong><span class=\"nc-red_bg\">cellules de Sertoli</span>-Leydig</strong> (souvent associées à une sécrétion hormonale).</li></ul></div>"},{"i":"b61b486d8558","n":306,"o":"306-5","u":"Diagnostic positif","t":"Connaître les principaux facteurs de risque/protecteurs associés au cancer de l’ovaire","q":"Quels sont les principaux facteurs protecteurs contre le cancer de l'ovaire ?","a":"<div class=\"notion-course\"><p>Les principaux facteurs protecteurs contre le cancer de l'ovaire sont :</p><ul><li>Ceux qui diminuent le nombre d'ovulations : la <strong><span class=\"nc-green_bg\">grossesse</span></strong>, la <strong><span class=\"nc-green_bg\">multiparité</span></strong>, l'<strong><span class=\"nc-green_bg\">allaitement</span></strong>, la <strong><span class=\"nc-pink nc-bold\">contraception orale</span> œstroprogestative</strong>.</li><li>Ceux qui suppriment le tissu cible : la <strong><span class=\"nc-pink_bg\">ligature des trompes</span></strong> et la <strong><span class=\"nc-pink_bg\">salpingectomie bilatérale</span></strong> (particulièrement si mutation BRCA).</li></ul></div>"},{"i":"c7326b1e1f7e","n":306,"o":"306-5","u":"Diagnostic positif","t":"Connaître les principaux facteurs de risque/protecteurs associés au cancer de l’ovaire","q":"Quels sont les principaux facteurs de risque génétiques du cancer de l'ovaire à rechercher ?","a":"<div class=\"notion-course\"><p>Les principaux facteurs de risque génétiques du cancer de l'ovaire sont :</p><ul><li>Des <strong>antécédents familiaux de 1er degré</strong>, augmentant le risque à 5% au cours de la vie.</li><li>Des <strong>mutations <span class=\"nc-blue_bg\">BRCA1</span>/<span class=\"nc-blue_bg\">BRCA2</span></strong> (80% des formes héréditaires, avant 60 ans, meilleur pronostic avec les inhibiteurs de PARP).</li><li>Le <strong><span class=\"nc-red nc-bold\">syndrome de Lynch</span></strong> (défaut MMR - MSI-H), impliquant principalement cancer colorectal et endomètre, mais aussi ovaire.</li></ul></div>"},{"i":"fce4e76ca714","n":306,"o":"306-5","u":"Diagnostic positif","t":"Connaître les principaux facteurs de risque/protecteurs associés au cancer de l’ovaire","q":"Quels sont les facteurs de risque extrinsèques et gynécologiques du cancer de l'ovaire ?","a":"<div class=\"notion-course\"><p>Les facteurs de risque extrinsèques et gynécologiques du cancer de l'ovaire sont :</p><ul><li><strong>Extrinsèques :</strong> le <strong><span class=\"nc-orange_bg\">tabagisme</span></strong>, l'<span class=\"nc-red nc-bold\">exposition professionnelle à l'</span><strong><span class=\"nc-red nc-bold\">amiante</span></strong>, le <strong>surpoids</strong>.</li><li><strong>Gynécologiques :</strong> l'augmentation du nombre de cycles (<span class=\"nc-blue_bg\">âge</span>, <strong><span class=\"nc-blue_bg\">nulliparité</span></strong>, <span class=\"nc-blue_bg\">puberté/règles précoces</span>, <span class=\"nc-blue_bg\">ménopause tardive</span>), l'<strong><span class=\"nc-red nc-bold\">infertilité</span></strong>, et ceux d'origine iatrogène (<strong>THM œstrogénique</strong>, clomifène/FIV).</li></ul></div>"},{"i":"ebe57b78afbf","n":306,"o":"306-2","u":"Définition","t":"Connaître les principaux types histologiques des tumeurs bénignes et malignes","q":"Que retenir concernant les principaux types histologiques des tumeurs bénignes et malignes ?","a":"<div class=\"notion-course\"><p>La <span>classification OMS 2020</span> affine la stratification de l'obj-0 en sous-types histologiques précis. L'enjeu n'est pas mnémotechnique : chaque sous-type a un <span>pronostic</span> et une <span>thérapeutique ciblée</span> propres (notamment les mutations <span><span class=\"nc-blue_bg\">BRCA1</span>/2</span>, l'<span>instabilité microsatellite</span> et les inhibiteurs de <span>PARP</span>).</p>\n\n      <table>\n        <thead>\n          <tr><th>Type</th><th>Bénin / Borderline</th><th>Malin</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Séreux</span></strong></td>\n            <td><strong>Bénin :</strong> cystadénome · adénofibrome · cystadénofibrome<br><strong>Borderline :</strong> séreuse borderline · micropapillaire</td>\n            <td>Adénocarcinome <span class=\"nc-red nc-bold\">séreux</span> <span>haut grade</span> <em>(le + fréquent)</em> · adénocarcinome <span class=\"nc-red nc-bold\">séreux</span> bas <span>grade</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mucineux</strong></td>\n            <td><strong>Bénin :</strong> cystadénome mucineux<br><strong>Borderline :</strong> mucineuse borderline</td>\n            <td>Adénocarcinome mucineux (expansif ou infiltratif)</td>\n          </tr>\n          <tr>\n            <td><strong>Endométrioïde</strong></td>\n            <td><strong>Bénin :</strong> cystadénome / adénofibrome endométrioïde<br><strong>Borderline :</strong> endométrioïde borderline</td>\n            <td>Adénocarcinome endométrioïde</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">À cellules claires</span></strong></td>\n            <td><strong>Bénin :</strong> cystadénome<br><strong>Borderline :</strong> borderline <span class=\"nc-red nc-bold\">à cellules claires</span></td>\n            <td>Adénocarcinome <span class=\"nc-red nc-bold\">à </span><span><span class=\"nc-red nc-bold\">cellules claires</span></span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Tumeurs <span class=\"nc-red nc-bold\">borderline</span> (TBO).</strong> Représentent <span>10-20 %</span> des tumeurs épithéliales non bénignes. Âge médian inférieur de <span><span class=\"nc-green_bg nc-bold\">-10 ans</span></span> aux tumeurs <span class=\"nc-red nc-bold\">malignes</span> (1/3 chez <span>&lt; 40 ans</span>). Excellent pronostic mais risque de <span class=\"nc-red nc-bold\">récidive</span> tardive (<span>&gt; 20 ans</span>). <span>IRM pelvienne</span> essentielle, mais seule l'analyse <span>histologique</span> permet le diagnostic.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 293 — Anapath</em></p></div>"},{"i":"11975b2b576c","n":306,"o":"306-3","u":"Epidémiologie","t":"Connaître l’épidémiologie et le pronostic des tumeurs bénignes et malignes","q":"Que retenir concernant l’épidémiologie et le pronostic des tumeurs bénignes et malignes ?","a":"<div class=\"notion-course\"><table>\n        <thead>\n          <tr><th>Type</th><th>Fréquence</th><th>Âge médian</th><th>Survie / <span>Pronostic</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Bénignes</strong></td>\n            <td>Majorité des tumeurs ovariennes</td>\n            <td><span>~ <span class=\"nc-pink nc-bold\">30 ans</span></span></td>\n            <td><strong>Bon <span>pronostic</span>.</strong> Guéries après <span>exérèse</span> chirurgicale pour fibrothécome, cystadénome <span class=\"nc-red nc-bold\">séreux</span> ou <span class=\"nc-red nc-bold\">mucineux</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Malignes</strong></td>\n            <td><span>5 200 nouveaux cas / an</span> (France, 2018)<br><span>5ᵉ cancer féminin</span> · <span>2ᵉ gynéco</span> après endomètre</td>\n            <td><span><span class=\"nc-pink nc-bold\">65-68 ans</span></span></td>\n            <td><span>4ᵉ cause de décès par cancer féminin</span> (1ʳᵉ par cancer gynéco)<br><span class=\"nc-yellow_bg\">Survie globale à</span><span><span class=\"nc-yellow_bg\"> 5 ans</span></span> : <span>45 %</span><br><span class=\"nc-green nc-bold\">FIGO I</span> : <span>90 %</span> · FIGO ≥ III : <span>&lt; 40 %</span><br>Diagnostic <span>tardif dans 75 %</span> des cas</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Facteurs pronostiques.</strong> Le facteur pronostique le plus important est la <strong><span class=\"nc-yellow_bg\">résécabilité de la maladie</span></strong> et le <strong><span class=\"nc-yellow_bg\">résidu tumoral post-opératoire</span></strong>. S'y associent l'<span>âge</span>, l'<span>état général</span>, le <span><span class=\"nc-red_bg\">type histologique</span></span>, le grade et la réponse à la chimiothérapie. Le pronostic est <span>amélioré</span> par la PEC dans des centres experts (taux de résection R0 supérieur, accès aux essais cliniques).</p>\n\n      <div class=\"callout callout-danger\">\n        <strong>Pronostic global <span class=\"nc-red nc-bold\">médiocre</span>.</strong> Le diagnostic au <span>stade tardif (75 % des cas)</span> explique la mortalité élevée du cancer de l'ovaire. La tumeur <strong>germinale</strong> est le <span class=\"nc-red_bg\">type histologique</span> de meilleur pronostic, car souvent découverte plus précocement chez la femme jeune.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers · 300 — Tumeur col-corps utérin · 312 — Tumeur sein · 124 — Ménopause - andropause</em></p></div>"},{"i":"2d138a8ef8d0","n":306,"o":"306-4","u":"Eléments physiopathologiques","t":"Connaître la physiopathologie des cancers de l’ovaire","q":"Que retenir concernant la physiopathologie des cancers de l’ovaire ?","a":"<div class=\"notion-course\"><p>Il existe <span>deux théories complémentaires</span> sur l'origine du cancer de l'ovaire. Toutes deux convergent vers une <span>origine multifocale</span>, ce qui explique la <span>latence <span class=\"nc-blue nc-bold\">clinique</span></span> et la <span><span class=\"nc-red nc-bold\">dissémination péritonéale</span> <span class=\"nc-green nc-bold\">précoce</span></span>.</p>\n\n      <table>\n        <thead>\n          <tr><th>Théorie</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Origine tubaire</strong></td>\n            <td>La <span>trompe de Fallope</span> serait le point de départ. Le <span><span class=\"nc-orange nc-bold\">carcinome séreux intra-épithélial tubaire</span> (STIC)</span> est la 1ʳᵉ <span>lésion</span> histologique des <span>carcinomes <span class=\"nc-red nc-bold\">séreux</span> haut grade</span> (= forme la plus fréquente). L'ovaire est secondairement envahi par des <span class=\"nc-blue_bg\">cellules</span> dysplasiques d'origine tubaire.</td>\n          </tr>\n          <tr>\n            <td><strong>Cicatrisation ovarienne</strong><br>(<em>ovulation incessante</em>)</td>\n            <td>À chaque <span>ovulation</span>, <span>rupture</span> de l'épithélium de surface → prolifération cicatricielle → <span><span class=\"nc-red nc-bold\">kystes</span> d'inclusion</span> → accumulation d'<span>anomalies génétiques</span> au fil des cycles. Justifie le rôle <span>protecteur</span> des situations qui diminuent les ovulations (<span>parité</span>, <span>allaitement</span>, <span>CO œstroprogestative</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table>\n        <thead>\n          <tr><th>Mode de dissémination</th><th>Cibles</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Loco-régional</strong><br>(péritoine ++)</td>\n            <td>Franchissement de la corticale ovarienne → dissémination très rapide vers les <span><span class=\"nc-red nc-bold\">organes pelviens</span></span>, puis vers <span>l'<span class=\"nc-red nc-bold\">ensemble de la cavité péritonéale</span></span> au gré du flux du liquide péritonéal (= <strong>carcinose péritonéale</strong>).</td>\n          </tr>\n          <tr>\n            <td><strong>À distance</strong></td>\n            <td>Dissémination <span>lymphatique</span> (ganglions <span class=\"nc-purple nc-bold\">pelviens</span> + <span class=\"nc-purple nc-bold\">lomboaortiques</span>), puis <span>hématogène</span> (poumons, <span class=\"nc-red nc-bold\">foie</span>, cerveau).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pourquoi un diagnostic si tardif ?</strong> L'extension péritonéale <span class=\"nc-green nc-bold\">précoce</span> et silencieuse explique que <span>3/4 des cancers sont diagnostiqués à un stade avancé</span> de carcinose. L'absence de <span>dépistage</span> efficace aggrave ce retard.\n      </div></div>"},{"i":"fe1bdfd13149","n":306,"o":"306-6","u":"Diagnostic","t":"Connaître les indications de la cœlioscopie","q":"Que retenir concernant les indications de la cœlioscopie ?","a":"<div class=\"notion-course\"><ul><li>Une masse annexielle n’impose pas toujours une cœlioscopie : les kystes simples à faible risque peuvent relever d’une surveillance adaptée.</li><li>Chirurgie si torsion/complication, <span class=\"nc-red nc-bold\">symptômes</span> persistants, taille ou aspect préoccupant, ou indication oncologique. Voie d’abord et geste selon risque de <span class=\"nc-red_bg\">malignité</span> et objectif de conservation.</li><li>Masse présumée bénigne : <span class=\"nc-pink nc-bold\">kystectomie</span> ou <span class=\"nc-pink nc-bold\">annexectomie</span> selon âge, réserve ovarienne et contexte, avec précautions pour éviter la <span class=\"nc-red nc-bold\">rupture</span> et analyse anatomopathologique.</li><li>Masse suspecte de malignité : adresser à une équipe de gynécologie oncologique pour stratégie de diagnostic/stadification ; éviter la ponction non planifiée d’une masse ovarienne isolée.</li><li>En maladie avancée, une biopsie de carcinose ou d’un site accessible peut être indiquée avant traitement néoadjuvant selon décision multidisciplinaire ; ne pas confondre ce geste avec la ponction d’un kyste isolé.</li></ul></div>"},{"i":"b41363686ab7","n":306,"o":"306-7","u":"Examens complémentaires","t":"Connaître les indications de l’imagerie d’une tumeur de l’ovaire","q":"Que retenir concernant les indications de l’imagerie d’une tumeur de l’ovaire ?","a":"<div class=\"notion-course\"><p>L'imagerie pelvienne suit une <span>hiérarchie stricte</span> selon le contexte. L'<span><span class=\"nc-blue nc-bold\">échographie</span> pelvienne</span> est l'examen de 1ʳᵉ intention devant toute suspicion de <span><span class=\"nc-red_bg\">masse</span></span><span class=\"nc-red_bg\"> pelvienne</span>, complétée par l'<span><span class=\"nc-blue_bg\">IRM</span></span> en cas d'incertitude, puis par la <span><span class=\"nc-yellow_bg\">TDM-TAP</span></span> pour le <span>bilan d'extension</span> après <span>diagnostic positif</span>.</p>\n\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Indications</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Échographie</span> pelvienne</strong><br>(1ʳᵉ intention)</td>\n            <td>Voie <span>sus-pubienne vessie pleine</span> + voie <span>endovaginale vessie vide</span> + <span><span><span class=\"nc-blue_bg\">échographie</span></span><span class=\"nc-blue_bg\"> abdominale</span></span> ± <span><span class=\"nc-blue_bg\">écho-doppler couleur</span></span>.<br>Classe la tumeur en <strong><span class=\"nc-green_bg\">kyste fonctionnel</span></strong> <span>vs</span> <strong><span class=\"nc-yellow_bg\">kyste organique</span></strong> <span>vs</span> <strong><span><span class=\"nc-red_bg\">critères de</span></span><span class=\"nc-red_bg\"> malignité</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-blue_bg\">IRM</span></span><span class=\"nc-blue_bg\"> abdomino-pelvienne</span></strong></td>\n            <td><strong>Indications :</strong> <span><span class=\"nc-yellow_bg\">masse</span></span><span class=\"nc-yellow_bg\"> ovarienne indéterminée</span> (caractérisation par <span>diffusion</span> + perfusion) · <span><span class=\"nc-blue nc-bold\">bilan d'extension</span></span><span class=\"nc-blue nc-bold\"> locorégional</span> des formes localisées · suspicion de TBO (intérêt majeur).<br><strong>Non-indication :</strong> pas d'intérêt si <span><span class=\"nc-blue nc-bold\">échographie</span></span> suspecte d'emblée une maladie avancée avec carcinose (on passe direct au <span><span class=\"nc-yellow_bg\">TDM</span></span><span class=\"nc-yellow_bg\">-TAP</span>).<br><strong><span>Classification</span> <span>O-RADS</span></strong> (<em>Ovarian-Adnexal Reporting &amp; Data System</em>) :<br><strong>O-RADS 1-2</strong> = presque toujours bénin → <span>surveillance possible</span><br><strong>O-RADS 3</strong> = risque faible → <span>avis spécialisé</span><br><strong>O-RADS 4-5</strong> = <span>tumeur borderline ou invasive suspectée</span> → <span><span class=\"nc-blue_bg\">IRM</span></span> injectée + <span>prise en charge chirurgicale</span></td>\n          </tr>\n          <tr>\n            <td><strong><span>TDM</span> thoraco-abdomino-pelvien</strong><br>(<span><span class=\"nc-yellow_bg\">TDM</span></span><span class=\"nc-yellow_bg\">-TAP</span>)</td>\n            <td><strong>Systématique</strong> pour le <span>bilan d'extension</span> après <span>diagnostic positif</span>. Apprécie l'importance et la distribution de la <span>carcinose péritonéale</span> (++ étage supérieur de l'abdomen), explore les chaînes ganglionnaires rétropéritonéales / pelviennes / <span class=\"nc-purple nc-bold\">lomboaortiques</span>. Coupes thoraciques : recherche d'<span>épanchement pleural</span> (fréquent <span>stade</span> IV) et de ganglions médiastinaux ou <span class=\"nc-yellow_bg nc-bold\">sus-claviculaires</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Optionnels</strong></td>\n            <td><strong><span><span>TEP</span>-<span>TDM</span></span> 18FDG :</strong> complément du <span>TDM</span> pour les <span><span class=\"nc-red nc-bold\">stades avancés</span></span> ou les <span><span class=\"nc-red nc-bold\">récidives</span></span> (suspicion de rechute avec <span>TDM</span> normal).<br><strong>Imagerie mammaire</strong> (<span>mammographie</span> + écho) : éliminer un cancer du <span class=\"nc-red nc-bold\">sein</span> concomitant en cas de <span class=\"nc-red nc-bold\">carcinose péritonéale</span> avec masses annexielles.<br><strong><span>Endoscopie</span> digestive</strong> (<span>FOGD</span> + <span>coloscopie</span>) : éliminer une origine digestive primitive si <span><span class=\"nc-pink nc-bold\">CA 19-9</span></span> augmenté ou image <span>TDM</span>-TAP suspecte.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table>\n        <thead>\n          <tr><th>Critères échographiques de <span class=\"nc-red_bg\">malignité</span></th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Taille de la <span>masse</span></strong></td>\n            <td><span>&gt; 7 cm</span> (cut-off rang A).</td>\n          </tr>\n          <tr>\n            <td><strong>Présence de cloisons</strong></td>\n            <td>Caractère <span>multiloculaire</span> · cloisons épaisses (<span>&gt; 3 mm</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Parois épaissies</strong></td>\n            <td>Irrégularités des parois interne ou externe — <em>signe majeur</em> de malignité.</td>\n          </tr>\n          <tr>\n            <td><strong>Composantes solides</strong></td>\n            <td><span><span class=\"nc-red_bg\">Végétations endo/exo-kystiques</span></span> plus ou moins épaisses et confluentes.</td>\n          </tr>\n          <tr>\n            <td><strong>Vascularisation <span>doppler</span></strong></td>\n            <td><span><span class=\"nc-yellow_bg\">Hypervascularisation</span></span> (néovascularisation) + <span><span class=\"nc-yellow_bg\">diminution de la résistivité</span></span> (vitesse de circulation sanguine).</td>\n          </tr>\n          <tr>\n            <td><strong>Signes associés</strong></td>\n            <td><span><span class=\"nc-red_bg\">Ascite</span></span> · <span><span class=\"nc-red_bg\">adénopathies</span></span> · <span><span class=\"nc-red_bg\">bilatéralité</span></span> · nodules de carcinose (peu visibles en écho, mieux vus en <span>TDM</span>).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>CAT échographique synthétique.</strong> <span>Critères de</span> bénignité tous présents (<span>&lt; 7 cm</span>, uniloculaire, anéchogène pur, parois fines, pas de végétation, pas de vascularisation pathologique, pas d'<span class=\"nc-red_bg\">ascite</span>) → <span><span class=\"nc-green_bg\">surveillance</span> écho à M1-M3</span>. <span class=\"nc-red_bg\">Persistance</span> à<span> 3 mois</span> → <span class=\"nc-yellow_bg\">kyste organique</span>. Critère(s) suspects → <span><span class=\"nc-blue_bg\">IRM</span></span><span class=\"nc-blue_bg\"> + </span><span><span class=\"nc-blue_bg\">marqueurs</span></span>. Carcinose / <span class=\"nc-red_bg\">ascite</span> → <span><span class=\"nc-yellow_bg\">TDM-TAP</span> injecté</span>.\n      </div>\n\n      <div class=\"callout callout-danger\">\n        <strong>Piège kyste dermoïde.</strong> Diagnostic souvent fait à l'écho seule grâce à l'aspect <span class=\"nc-blue_bg\">hétérogène</span> + zones hyperéchogènes (<span class=\"nc-blue nc-bold\">cheveux</span>, dents) + <strong>protubérance de Rokitanski</strong>. Le <span>TDM</span> aide en montrant le <span>contenu graisseux caractéristique</span> + calcifications. Mais <span>risque élevé de <span class=\"nc-orange nc-bold\">torsion</span> d'annexe</span> (kyste <span class=\"nc-red nc-bold\">lourd</span>).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 44 — Tuméfaction pelvienne · 40 — Algies pelviennes</em></p></div>"},{"i":"ad0197567f0d","n":306,"o":"306-8","u":"Examens complémentaires","t":"Connaître l’intérêt diagnostique et pronostique de l’anapath","q":"Que retenir concernant l’intérêt diagnostique et pronostique de l’anapath ?","a":"<div class=\"notion-course\"><div class=\"callout callout-danger\">\n        <strong><span class=\"nc-red nc-bold\">Spécificité</span> cancer de l'ovaire.</strong> C'est l'un des <span>rares cancers</span> dont le diagnostic n'est <span>pas obtenu en pré-opératoire</span> — le <span class=\"nc-red nc-bold\">diagnostic est </span><span><span class=\"nc-red nc-bold\">chirurgical</span></span><span class=\"nc-red nc-bold\"> dans la majorité des cas</span>. Recommandé <span>avant <span class=\"nc-yellow_bg nc-bold\">toute</span> chimiothérapie</span>.\n      </div>\n\n      <table>\n        <thead>\n          <tr><th><span>Stade</span> FIGO</th><th>Modalité de prélèvement</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Stades précoces</strong><br>(FIGO 1-2)</td>\n            <td>Exploration chirurgicale → <strong><span class=\"nc-green_bg\">annexectomie diagnostique</span></strong> + anapath.<br><strong>&lt; 10 cm :</strong> <span>cœlioscopie</span> privilégiée.<br><strong><span>&gt; 10 cm</span> ou <span class=\"nc-orange_bg\">diagnostic incertain</span> :</strong> <span><span class=\"nc-orange_bg nc-bold\">laparotomie</span></span> (éviter <span><span class=\"nc-red nc-bold\">rupture</span></span>).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Stades avancés</span></strong><br>(FIGO 3-4)</td>\n            <td><strong>Cœlioscopie diagnostique</strong> pour <span>biopsies</span> multiples des nodules de carcinose.</td>\n          </tr>\n          <tr>\n            <td><strong>Patiente non opérable</strong></td>\n            <td><strong><span>Biopsie</span> sous <span class=\"nc-blue_bg\">radiologie interventionnelle</span></strong> (percutanée sous <span>TDM</span> ou <span>échographie</span> d'un <span>nodule</span> de carcinose).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table>\n        <thead>\n          <tr><th>Type de prélèvement</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Diagnostic positif</span></strong></td>\n            <td><span class=\"nc-yellow_bg nc-bold\">Matériel </span><strong><span class=\"nc-yellow_bg nc-bold\">biopsique</span></strong> (et <span>non cytologique</span>) · <span>biopsies</span> <span>multiples</span> et de <span>bonne taille</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Mutations somatiques</strong><br>(sur la tumeur)</td>\n            <td><strong><span class=\"nc-blue_bg\">BRCA1</span> / <span class=\"nc-blue_bg\">BRCA2</span> systématique</strong> : si mutation → conseil oncogénétique + <span>inhibiteurs de PARP</span> adjuvant.<br><strong><span>Score</span> HRD</strong> (<em>Homologous Recombination Deficiency</em>) : recherché si <span>BRCA sauvage</span> — conditionne l'éligibilité aux <span>PARPi (olaparib, niraparib)</span> en 1ʳᵉ ligne.<br><strong>Instabilité microsatellites (Lynch) :</strong> non systématique, à réaliser si cancer <span>&lt; 70 ans</span> ou histoire personnelle / familiale évocatrice.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 293 — Anapath · 292 — Diagnostic des cancers</em></p></div>"},{"i":"e574116267c7","n":306,"o":"306-9","u":"Examens complémentaires","t":"Connaître les principaux marqueurs sériques et leur bon usage dans les tumeurs de l’ovaire","q":"Que retenir concernant les principaux marqueurs sériques et leur bon usage dans les tumeurs de l’ovaire ?","a":"<div class=\"notion-course\"><p>Le choix des marqueurs sériques dépend du contexte <span class=\"nc-blue nc-bold\">clinique</span> (femme jeune / âgée) et de la suspicion histologique (épithéliale / germinale / cordon sexuel). Le <span><span class=\"nc-pink nc-bold\">CA 125</span></span> est le marqueur de référence du cancer épithélial — mais ni assez sensible ni assez spécifique pour porter le diagnostic à lui seul.</p>\n\n      <table>\n        <thead>\n          <tr><th>Contexte</th><th>Marqueurs à doser</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Suspicion de cancer épithélial</strong><br>(1ʳᵉ intention)</td>\n            <td><strong><span><span class=\"nc-yellow_bg\">CA 125</span></span></strong> (assez spécifique) · <strong><span><span class=\"nc-yellow_bg\">CA 19-9</span></span></strong> (souvent élevé dans les formes mucineuses) · <strong><span><span class=\"nc-yellow_bg\">ACE</span></span></strong> (moins spécifique).</td>\n          </tr>\n          <tr>\n            <td><strong>Suspicion tumeur germinale</strong><br>(femme <span>jeune</span>)</td>\n            <td><strong><span><span class=\"nc-blue_bg\">LDH</span></span> + α-fœtoprotéine</strong> (élevés dans les dysembryomes) · <strong><span class=\"nc-blue_bg\">hCG</span></strong> (élevés dans les choriocarcinomes).</td>\n          </tr>\n          <tr>\n            <td><strong>Suspicion tumeur des <span class=\"nc-pink nc-bold\">cordons sexuels</span></strong><br>(signes d'hyperœstrogénie ou tumeur de la granulosa)</td>\n            <td><strong><span class=\"nc-pink_bg\">Estradiol</span> + AMH + <span class=\"nc-pink_bg\">inhibine B</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span><span class=\"nc-yellow_bg\">Masse</span></span><span class=\"nc-yellow_bg\"> ovarienne indéterminée</span> à l'imagerie</strong></td>\n            <td><strong><span class=\"nc-yellow_bg\">HE4</span></strong> (<em>Human Epididymal Protein 4</em>) — peu utilisé, <span>non remboursé</span>. S'interprète selon le <span><span class=\"nc-blue nc-bold\">score ROMA</span></span> (statut ménopausique + <span>CA 125</span> + <span><span class=\"nc-yellow_bg\">HE4</span></span>) — cut-off : <span>11,4 % préménopause</span> · <span>29,9 % postménopause</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">\n        <strong><span><span class=\"nc-pink nc-bold\">CA 125</span></span> : pièges à connaître.</strong> <strong><span class=\"nc-red nc-bold\">Sensibilité imparfaite</span></strong> : <span>faux négatifs possibles</span> (un <span><span class=\"nc-pink nc-bold\">CA 125</span> normal n'élimine pas un cancer</span>). <strong><span class=\"nc-red nc-bold\">Spécificité</span> <span class=\"nc-red nc-bold\">imparfaite</span></strong> : c'est aussi un <span>marqueur d'irritation péritonéale</span> (<span>endométriose</span>, <span>infection</span>, autres carcinomes non ovariens). Donc <span>il n'est pas recommandé</span> de se fonder uniquement sur le <span><span class=\"nc-pink nc-bold\">CA 125</span></span> sérique pour évaluer la résécabilité d'une carcinose.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong><span>Suivi</span> post-traitement.</strong> Si <span><span class=\"nc-pink nc-bold\">CA 125</span> &lt; 10 UI/mL</span> après traitement, <span class=\"nc-yellow_bg nc-bold\">toute</span> élévation <span>&gt; 20 UI/mL</span> contrôlée à<span> 15 jours</span> est suspecte de <span class=\"nc-red nc-bold\">récidive</span> — peut précéder les signes cliniques. La décroissance des marqueurs juge en partie l'efficacité du traitement.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 290 — Epidémiologie cancers</em></p></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d941818597b1c7181c564dfa?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."}};
